#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def load(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def save(path: str, value: str) -> None:
    (ROOT / path).write_text(value, encoding="utf-8")


def replace_once(path: str, old: str, new: str) -> None:
    value = load(path)
    count = value.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected one anchor, found {count}: {old[:120]!r}")
    save(path, value.replace(old, new, 1))


def replace_between(path: str, start: str, end: str, replacement: str) -> None:
    value = load(path)
    left = value.find(start)
    if left < 0:
        raise RuntimeError(f"{path}: missing start anchor {start!r}")
    right = value.find(end, left)
    if right < 0:
        raise RuntimeError(f"{path}: missing end anchor {end!r}")
    save(path, value[:left] + replacement + value[right:])


